BEGIN;

-- Enlaza la mención de Radhamés Aracena que ya existía en la ficha de Tony Seval.
--
-- La biografía de Tony Seval nombraba a "Radhamés Aracena" en los dos idiomas desde
-- que se escribió, pero él no estaba en la base, así que el nombre quedó como
-- texto muerto. Al crear su ficha (20260907010100) esa mención pasa a ser un
-- enlace de verdad.
--
-- No cambia ni una palabra de la prosa: una referencia se renderiza como su
-- displayText, que es el mismo texto que ya estaba. Cambia el nodo, que se parte
-- en tres, y aparece la fila de relación.
--
-- El occurrence_id vive DENTRO del JSON del documento, así que el documento y su
-- fila se escriben juntos o no se escribe ninguno.
--
-- Aplicado directamente por DATABASE_URL. No corrió ninguna función de Vercel y
-- no se revalidó nada.

UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Tony Seval — Felipe Antonio Sepúlveda Caraballo, born in La Romana on 5 February 1954 — was a Dominican merengue singer, composer and conguero. He was known in the trade as Kuky, he worked from 1970, and he was thirty-one when he died in police custody in 1985.","type":"text"}]},{"type":"paragraph","content":[{"text":"The conga on his shoulder","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"He moved to Santo Domingo as a teenager and learned the city’s concert halls from inside the bands rather than in front of them. The Fania All-Stars were his model. He played in the Orquesta de Juan Luis y sus Mulatos, then in the Típica Dominicana alongside ","type":"text"},{"type":"artistReference","attrs":{"artistId":"f050869b-f4c0-4281-b883-bce0120ad9b2","displayText":"Aníbal Bravo","occurrenceId":"1959d8bf-aa55-489f-ad67-2a4cae9f7600"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"2b644026-3e99-4229-a729-003f04103f30","displayText":"Blas Durán","occurrenceId":"1993f552-6e26-4d12-84c9-179481867620"}},{"text":" and Bobby Rafael, where he was the conguero.","type":"text"}]},{"type":"paragraph","content":[{"text":"Around 1975 and 1976 people in Villas Agrícolas knew him by sight: the man walking through the barrio with his conga over his shoulder. He was an expert on the instrument before anyone thought of him as a singer.","type":"text"}]},{"type":"paragraph","content":[{"text":"Kuky Sabor y Son","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"At the end of 1978 he recorded for ","type":"text"},{"type":"artistReference","attrs":{"artistId":"a08ab62e-ec7b-4770-ae52-60c1fcea6a08","displayText":"Radhamés Aracena","occurrenceId":"5cd89ace-aeec-44a8-94f8-77038a4bbf89"}},{"text":"’s Radio Guarachita label with his own group, Kuky Sabor y Son. It was his debut as a singer and as a leader, and La Dura was the song that took.","type":"text"}]},{"type":"paragraph","content":[{"text":"When merengue broke open in 1982 he worked the other side of the business too — percussionist for hire, promoter, contractor for the big orchestras of the moment.","type":"text"}]},{"type":"paragraph","content":[{"text":"Tony Seval y Los Gitanos","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Early in 1984, backed by the Disco Mundo label, he formed Tony Seval y Los Gitanos and made a ten-track album, most of it his own writing. Zayda, Pa Bochinche, Gracias, Ton Din Don, Dame un Chance, La Maleta and Me Está Provocando came off it.","type":"text"}]},{"type":"paragraph","content":[{"text":"The record was called El Muerto. It went to the top of Dominican radio, his orchestra was booked across the country, and his band played the Show del Mediodía every Wednesday.","type":"text"}]},{"type":"paragraph","content":[{"text":"The arrest","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"On 22 October 1985 he was arrested and taken to the police station in Villa Francisca and then to the National Police headquarters, on an accusation of drug trafficking.","type":"text"}]},{"type":"paragraph","content":[{"text":"Reports of his treatment in custody led to a public denunciation of the arrest as illegal. The television producer ","type":"text"},{"type":"artistReference","attrs":{"artistId":"faff18bd-3dbc-477a-bc38-859d611887f0","displayText":"Yaqui Núñez del Risco","occurrenceId":"bed51a5c-8a56-4140-8f6f-57c4ac4bcfc7"}},{"text":" and the journalist Luis Eduardo Lora Iglesias, both of the Show del Mediodía, took up the case. Almost nobody was allowed near him.","type":"text"}]},{"type":"paragraph","content":[{"text":"He died on 24 October, two days after the arrest. The account given at the time was that he had been beaten by other prisoners in the cell he was held in. Nothing about it was ever established, and forty years on the Dominican press still marks the date as a death that was never explained.","type":"text"}]}]}'::jsonb,
       revision = 5, updated_at = now()
 WHERE id = '52e3bc09-e51f-4dd7-8c0f-62f68d850a1f'::uuid;
INSERT INTO editorial_entity_references
  (editorial_document_id, occurrence_id, entity_type, target_artist_id)
VALUES ('52e3bc09-e51f-4dd7-8c0f-62f68d850a1f'::uuid, '5cd89ace-aeec-44a8-94f8-77038a4bbf89'::uuid, 'artist', 'a08ab62e-ec7b-4770-ae52-60c1fcea6a08'::uuid)
ON CONFLICT DO NOTHING;

UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Tony Seval —Felipe Antonio Sepúlveda Caraballo, nacido en La Romana el 5 de febrero de 1954— fue un cantante, compositor y conguero de merengue dominicano. En el medio le decían Kuky, trabajó desde 1970, y tenía treinta y un años cuando murió bajo custodia policial en 1985.","type":"text"}]},{"type":"paragraph","content":[{"text":"La conga al hombro","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Se mudó a Santo Domingo de adolescente y aprendió las salas de concierto de la capital desde dentro de las bandas, no delante de ellas. Su modelo era la Fania All-Stars. Tocó en la Orquesta de Juan Luis y sus Mulatos, y después en la Típica Dominicana junto a ","type":"text"},{"type":"artistReference","attrs":{"artistId":"f050869b-f4c0-4281-b883-bce0120ad9b2","displayText":"Aníbal Bravo","occurrenceId":"00e03620-910d-4baa-8c15-3a45ad69ac0c"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"2b644026-3e99-4229-a729-003f04103f30","displayText":"Blas Durán","occurrenceId":"c3167557-772c-4d3d-be8b-9d527dcb9f76"}},{"text":" y Bobby Rafael, donde era el conguero.","type":"text"}]},{"type":"paragraph","content":[{"text":"Por 1975 y 1976 la gente de Villas Agrícolas lo conocía de vista: el hombre que cruzaba el barrio con la conga al hombro. Era un ejecutante experto del instrumento antes de que nadie pensara en él como cantante.","type":"text"}]},{"type":"paragraph","content":[{"text":"Kuky Sabor y Son","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"A finales de 1978 grabó para el sello Radio Guarachita, de ","type":"text"},{"type":"artistReference","attrs":{"artistId":"a08ab62e-ec7b-4770-ae52-60c1fcea6a08","displayText":"Radhamés Aracena","occurrenceId":"11c13da5-7170-472c-a410-95d0d735b8d5"}},{"text":", con su propio grupo, Kuky Sabor y Son. Fue su debut como cantante y como líder, y La Dura fue el tema que prendió.","type":"text"}]},{"type":"paragraph","content":[{"text":"Cuando el merengue reventó en 1982 trabajó también del otro lado del negocio: percusionista de alquiler, promotor, contratista de las orquestas grandes del momento.","type":"text"}]},{"type":"paragraph","content":[{"text":"Tony Seval y Los Gitanos","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"A principios de 1984, respaldado por el sello Disco Mundo, formó Tony Seval y Los Gitanos e hizo un disco de diez cortes, casi todos de su autoría. De ahí salieron Zayda, Pa Bochinche, Gracias, Ton Din Don, Dame un Chance, La Maleta y Me Está Provocando.","type":"text"}]},{"type":"paragraph","content":[{"text":"El disco se llamaba El Muerto. Llegó a los primeros lugares de la radio dominicana, su orquesta se contrataba en todo el país, y su banda tocaba en el Show del Mediodía todos los miércoles.","type":"text"}]},{"type":"paragraph","content":[{"text":"El arresto","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"El 22 de octubre de 1985 fue apresado y llevado al destacamento policial de Villa Francisca y de ahí al Palacio de la Policía Nacional, bajo una acusación de tráfico de drogas.","type":"text"}]},{"type":"paragraph","content":[{"text":"Lo que se supo del trato que recibió detenido llevó a una denuncia pública del arresto como ilegal. El productor de televisión ","type":"text"},{"type":"artistReference","attrs":{"artistId":"faff18bd-3dbc-477a-bc38-859d611887f0","displayText":"Yaqui Núñez del Risco","occurrenceId":"5c94a1ad-cc6a-4151-8c98-f0e2354a47a6"}},{"text":" y el periodista Luis Eduardo Lora Iglesias, los dos del Show del Mediodía, tomaron el caso. Casi nadie pudo acercársele.","type":"text"}]},{"type":"paragraph","content":[{"text":"Murió el 24 de octubre, dos días después del arresto. La versión que se dio entonces fue que lo habían golpeado otros presos en la celda donde estaba. Nunca se estableció nada, y cuarenta años después la prensa dominicana sigue marcando la fecha como una muerte que jamás se explicó.","type":"text"}]}]}'::jsonb,
       revision = 3, updated_at = now()
 WHERE id = '85a299c8-eaec-42ab-81f8-0b880fbc8498'::uuid;
INSERT INTO editorial_entity_references
  (editorial_document_id, occurrence_id, entity_type, target_artist_id)
